var owner="loot";var repo="loot";var xhr=new XMLHttpRequest;xhr.addEventListener("load",function(){var e=JSON.parse(this.responseText);var t=0;for(var n=0;n<e.length;++n){for(var r=0;r<e[n].assets.length;++r){t+=e[n].assets[r].download_count}}console.log(t)});xhr.open("GET","https://api.github.com/repos/"+owner+"/"+repo+"/releases");xhr.send()